CREATE TABLE schema_migrations (version VARCHAR(64) PRIMARY KEY, sha256 CHAR(64) NOT NULL, applied_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
CREATE TABLE workspaces (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL) ENGINE=InnoDB;
CREATE TABLE profiles (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, full_name VARCHAR(120) NOT NULL, password_hash VARCHAR(256) NOT NULL, role ENUM('owner','admin','editor','qa','viewer') NOT NULL, is_approved BOOLEAN NOT NULL DEFAULT FALSE, is_blocked BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (workspace_id) REFERENCES workspaces(id)) ENGINE=InnoDB;
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, profile_id CHAR(36) NOT NULL, expires_at DATETIME(3) NOT NULL, revoked_at DATETIME(3), FOREIGN KEY(profile_id) REFERENCES profiles(id), INDEX(profile_id)) ENGINE=InnoDB;
CREATE TABLE auth_attempts (bucket CHAR(64) PRIMARY KEY, total INT UNSIGNED NOT NULL, expires_at DATETIME(3) NOT NULL) ENGINE=InnoDB;
CREATE TABLE business_inquiries (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, receipt VARCHAR(24) NOT NULL UNIQUE, payload JSON NOT NULL, status ENUM('new','qualified','discovery','proposal','won','lost','archived') NOT NULL DEFAULT 'new', admin_notes VARCHAR(2000), handled_by CHAR(36), contact_role VARCHAR(120), offer_interest VARCHAR(64) NOT NULL, lost_reason VARCHAR(64), lost_reason_detail VARCHAR(500), won_evidence_type VARCHAR(64), won_evidence_at DATETIME(3), created_at DATETIME(3) NOT NULL, consent_at DATETIME(3) NOT NULL, status_changed_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(handled_by) REFERENCES profiles(id), INDEX(workspace_id,created_at)) ENGINE=InnoDB;
CREATE TABLE ingest_receipts (receipt VARCHAR(24) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, remote_id CHAR(36) NOT NULL UNIQUE, payload_hash CHAR(64) NOT NULL, consent_version VARCHAR(64) NOT NULL, created_at DATETIME(3) NOT NULL, FOREIGN KEY(remote_id) REFERENCES business_inquiries(id), FOREIGN KEY(workspace_id) REFERENCES workspaces(id)) ENGINE=InnoDB;
CREATE TABLE ingest_nonces (nonce CHAR(64) PRIMARY KEY, expires_at DATETIME(3) NOT NULL) ENGINE=InnoDB;
CREATE TABLE business_inquiry_notifications (id CHAR(36) PRIMARY KEY, inquiry_id CHAR(36) NOT NULL UNIQUE, workspace_id CHAR(36) NOT NULL, reference_code VARCHAR(24) NOT NULL, notification_kind VARCHAR(64) NOT NULL, status ENUM('unread','read','archived') NOT NULL DEFAULT 'unread', created_at DATETIME(3) NOT NULL, read_at DATETIME(3), read_by CHAR(36), FOREIGN KEY(inquiry_id) REFERENCES business_inquiries(id), FOREIGN KEY(read_by) REFERENCES profiles(id)) ENGINE=InnoDB;
CREATE TABLE audit_events (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, actor_id CHAR(36), object_id CHAR(36) NOT NULL, event VARCHAR(64) NOT NULL, created_at DATETIME(3) NOT NULL) ENGINE=InnoDB;
CREATE TABLE private_files (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, inquiry_id CHAR(36) NOT NULL, storage_key CHAR(36) NOT NULL UNIQUE, mime VARCHAR(64) NOT NULL, sha256 CHAR(64) NOT NULL, bytes INT UNSIGNED NOT NULL, FOREIGN KEY(inquiry_id) REFERENCES business_inquiries(id)) ENGINE=InnoDB;
